def str_to_date(s, input_fmt_num):
    """Parse a date string using the given format number."""
    s = s.strip()
    # Check for short forms
    today = datetime.date.today()
    if s.lower() == 'today':
        return today
    if s.lower() == 'tomorrow':
        return today + datetime.timedelta(days=1)
    if s.lower() == 'yesterday':
        return today - datetime.timedelta(days=1)
    if s.lower() == 'now':
        return today

    # Check for weekday names
    weekdays = ['mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun']
    wday_full = ['monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday']
    s_lower = s.lower()
    for i, (short, full) in enumerate(zip(weekdays, wday_full)):
        if s_lower == short or s_lower == full:
            # Find next occurrence of this weekday
            # Note: Mon=0, Sun=6 in Python's weekday()
            # But in calcurse's context, Sun=0, Mon=1, ..., Sat=6
            # In Python: Mon=0, Tue=1, ..., Sun=6
            target = i  # 0=Mon in Python
            days_ahead = (target - today.weekday()) % 7
            if days_ahead == 0:
                days_ahead = 7
            return today + datetime.timedelta(days=days_ahead)

    # Parse using format
    fmt = INPUT_DATEFMT.get(input_fmt_num, "%m/%d/%Y")

    # Try with 4-digit year
    try:
        return datetime.datetime.strptime(s, fmt).date()
    except ValueError:
        pass

    # Try with 2-digit year  
    if fmt.endswith('%Y'):
        try:
            d = datetime.datetime.strptime(s, fmt[:-2] + '%y').date()
            return d
        except ValueError:
            pass

    raise ValueError(f"Cannot parse date: {s}")


def parse_date_with_time(s, input_fmt_num):
    """Parse a date with optional time specification.
    Returns (date, time_minutes_or_None)"""
    s = s.strip()
    # Check if there's a time part
    parts = s.rsplit(' ', 1)
    if len(parts) == 2:
        # Try to parse the second part as HH:MM time
        time_part = parts[1]
        time_match = re.match(r'^(\d{1,2}):(\d{2})$', time_part)
        if time_match:
            try:
                date = str_to_date(parts[0], input_fmt_num)
                h = int(time_match.group(1))
                m = int(time_match.group(2))
                return date, h * 60 + m
            except ValueError:
                pass

    return str_to_date(s, input_fmt_num), None


