def seconds_to_hhmm(secs):
    """Convert epoch seconds to HH:MM of the day."""
    dt = datetime.datetime.utcfromtimestamp(secs)
    return f"{dt.hour:02d}:{dt.minute:02d}"


# Recurring event frequency types
FREQ_DAILY = 'D'
FREQ_WEEKLY = 'W'
FREQ_MONTHLY = 'M'
FREQ_YEARLY = 'Y'


class RecurItem:
    """A recurring calendar item (appointment or event)."""
    def __init__(self, freq, interval, until=None, exceptions=None, 
                 bydays=None, bymonthdays=None, bymonths=None):
        """
        freq: 'D', 'W', 'M', 'Y'
        interval: integer
        until: datetime.date or None (no end)
        exceptions: list of datetime.date  
        bydays: list of integers (0=Sun, 1=Mon, ..., 6=Sat for simple;
                sign(n)*(abs(n)*7+day) for positional)
        bymonthdays: list of integers (1-31 or -1 to -31)
        bymonths: list of integers (1-12)
        """
        self.freq = freq
        self.interval = interval
        self.until = until
        self.exceptions = exceptions or []
        self.bydays = bydays or []
        self.bymonthdays = bymonthdays or []
        self.bymonths = bymonths or []

    def to_str(self, date_fmt):
        """Convert recurring rule to string representation in calcurse format."""
        parts = [f"{self.interval}{self.freq}"]
        if self.until:
            parts.append(f"-> {self.until.strftime('%m/%d/%Y')}")
        # Add extra specifiers
        for day in sorted(self.bymonthdays, key=lambda x: (x < 0, abs(x))):
            parts.append(f"d{day}")
        for day in sorted(self.bydays):
            parts.append(f"w{day}")
        for month in sorted(self.bymonths):
            parts.append(f"m{month}")
        # Add exceptions
        for exc in sorted(self.exceptions):
            parts.append(f"!{exc.strftime('%m/%d/%Y')}")
        return "{" + " ".join(parts) + "}"

    @classmethod
    def from_str(cls, s):
        """Parse a recur string like {2D -> 02/01/2000 !01/15/2000}"""
        s = s.strip('{}')
        parts = s.split()
        if not parts:
            return None

        # Parse frequency
        freq_match = re.match(r'^(\d+)([DWMY])$', parts[0])
        if not freq_match:
            return None
        interval = int(freq_match.group(1))
        freq = freq_match.group(2)

        until = None
        exceptions = []
        bydays = []
        bymonthdays = []
        bymonths = []

        i = 1
        while i < len(parts):
            part = parts[i]
            if part == '->':
                i += 1
                if i < len(parts):
                    try:
                        until = datetime.datetime.strptime(parts[i], '%m/%d/%Y').date()
                    except ValueError:
                        pass
            elif part.startswith('!'):
                try:
                    exc_date = datetime.datetime.strptime(part[1:], '%m/%d/%Y').date()
                    exceptions.append(exc_date)
                except ValueError:
                    pass
            elif part.startswith('w'):
                try:
                    bydays.append(int(part[1:]))
                except ValueError:
                    pass
            elif part.startswith('d'):
                try:
                    bymonthdays.append(int(part[1:]))
                except ValueError:
                    pass
            elif part.startswith('m'):
                try:
                    bymonths.append(int(part[1:]))
                except ValueError:
                    pass
            i += 1

        return cls(freq, interval, until, exceptions, bydays, bymonthdays, bymonths)

    def occurrences(self, start_date, query_start=None, query_end=None):
        """Generate all occurrence dates of this recurring item starting from start_date.
        Returns dates where the item occurs, filtered by query range."""

        occurrences = []

        if query_start is None:
            query_start = start_date
        if query_end is None:
            # No end - we need a limit
            query_end = datetime.date(2037, 12, 31)

        # Generate occurrences
        if self.freq == FREQ_DAILY:
            curr = start_date
            while True:
                if self.until and curr > self.until:
                    break
                if curr > query_end:
                    break
                if curr not in self.exceptions:
                    if self._matches_filters(curr):
                        if curr >= query_start:
                            occurrences.append(curr)
                curr += datetime.timedelta(days=self.interval)

        elif self.freq == FREQ_WEEKLY:
            # Generate week-by-week
            curr = start_date
            while True:
                if self.until and curr > self.until:
                    break
                if curr > query_end:
                    break
                if self.bydays:
                    # Generate for each specified day in this week
                    week_start = curr - datetime.timedelta(days=curr.weekday())  # Monday
                    for wd in range(7):
                        day = week_start + datetime.timedelta(days=wd)
                        # Convert Python weekday (0=Mon) to calcurse (0=Sun, 1=Mon, ..., 6=Sat)
                        calc_wd = (wd + 1) % 7  # 0=Sun,1=Mon,...,6=Sat
                        if calc_wd in self.bydays:
                            if day >= start_date:
                                if self.until and day > self.until:
                                    continue
                                if day > query_end:
                                    continue
                                if day not in self.exceptions:
                                    if day >= query_start:
                                        occurrences.append(day)
                else:
                    if curr not in self.exceptions:
                        if curr >= query_start:
                            occurrences.append(curr)
                curr += datetime.timedelta(weeks=self.interval)

        elif self.freq == FREQ_MONTHLY:
            curr_month = start_date
            while True:
                if curr_month > query_end:
                    break
                if self.until and curr_month > self.until:
                    break

                # Generate monthly occurrences
                monthly_days = self._monthly_occurrences(curr_month)
                for day in monthly_days:
                    if day < start_date:
                        continue
                    if self.until and day > self.until:
                        continue
                    if day > query_end:
                        continue
                    if day in self.exceptions:
                        continue
                    if day >= query_start:
                        occurrences.append(day)

                # Advance by interval months
                month = curr_month.month + self.interval
                year = curr_month.year + (month - 1) // 12
                month = ((month - 1) % 12) + 1
                try:
                    curr_month = datetime.date(year, month, curr_month.day)
                except ValueError:
                    # Day out of range for this month
                    import calendar
                    last_day = calendar.monthrange(year, month)[1]
                    curr_month = datetime.date(year, month, last_day)

        elif self.freq == FREQ_YEARLY:
            curr = start_date
            while True:
                if self.until and curr > self.until:
                    break
                if curr > query_end:
                    break

                # Generate yearly occurrences for this base date
                yearly_days = self._yearly_occurrences(curr)
                for day in yearly_days:
                    if day < start_date:
                        continue
                    if self.until and day > self.until:
                        continue
                    if day > query_end:
                        continue
                    if day in self.exceptions:
                        continue
                    if day >= query_start:
                        occurrences.append(day)

                try:
                    curr = datetime.date(curr.year + self.interval, curr.month, curr.day)
                except ValueError:
                    import calendar
                    last_day = calendar.monthrange(curr.year + self.interval, curr.month)[1]
                    curr = datetime.date(curr.year + self.interval, curr.month, last_day)

        return sorted(set(occurrences))

    def _matches_filters(self, day):
        """Check if a day matches the bymonths/bydays/bymonthdays filters."""
        if self.bymonths and day.month not in self.bymonths:
            return False
        if self.bymonthdays:
            import calendar
            last_day = calendar.monthrange(day.year, day.month)[1]
            month_days = set()
            for md in self.bymonthdays:
                if md > 0:
                    month_days.add(md)
                else:
                    month_days.add(last_day + md + 1)
            if day.day not in month_days:
                return False
        if self.bydays:
            # Simple BYDAY (no position): 0=Sun, 1=Mon, ..., 6=Sat
            # day.weekday() in Python: 0=Mon, ..., 6=Sun
            # Convert to calcurse: (day.weekday() + 1) % 7
            calc_wd = (day.weekday() + 1) % 7
            simple_days = [d for d in self.bydays if abs(d) < 7]
            positional_days = [d for d in self.bydays if abs(d) >= 7]

            matched = False
            if simple_days:
                if calc_wd in simple_days:
                    matched = True
            if positional_days:
                for pd in positional_days:
                    if self._matches_positional_byday(day, pd):
                        matched = True
                        break
            if not matched and (simple_days or positional_days):
                return False
        return True

    def _matches_positional_byday(self, day, encoded_val):
        """Check if a day matches an encoded positional BYDAY value."""
        if encoded_val >= 7:
            position = encoded_val // 7
            weekday = encoded_val % 7  # 0=Sun, 1=Mon, ..., 6=Sat
        else:  # encoded_val <= -7
            position = -((-encoded_val) // 7)
            weekday = (-encoded_val) % 7

        # Convert weekday to Python weekday (0=Mon, ..., 6=Sun)
        # calcurse: 0=Sun, 1=Mon, ..., 6=Sat
        # Python: 0=Mon, ..., 6=Sun
        py_wd = (weekday - 1) % 7  # calcurse -> python

        if day.weekday() != py_wd:
            return False

        if position > 0:
            # Find the nth occurrence of weekday in the month
            first_day = day.replace(day=1)
            first_wd_offset = (py_wd - first_day.weekday()) % 7
            nth_day = first_day.day + first_wd_offset + (position - 1) * 7
            return day.day == nth_day
        else:  # position < 0
            import calendar
            last_day_num = calendar.monthrange(day.year, day.month)[1]
            last_day = day.replace(day=last_day_num)
            last_wd_offset = (last_day.weekday() - py_wd) % 7
            nth_day = last_day_num - last_wd_offset + (position + 1) * 7
            return day.day == nth_day

    def _monthly_occurrences(self, base_date):
        """Get all occurrences in the same month as base_date."""
        import calendar
        year = base_date.year
        month = base_date.month
        last_day = calendar.monthrange(year, month)[1]

        days = []

        if not self.bydays and not self.bymonthdays:
            # Just this day of the month
            try:
                days.append(datetime.date(year, month, base_date.day))
            except ValueError:
                pass
            return days

        if self.bymonthdays:
            for md in self.bymonthdays:
                if md > 0:
                    d = md
                else:
                    d = last_day + md + 1
                if 1 <= d <= last_day:
                    candidate = datetime.date(year, month, d)
                    if self._day_matches_bydays(candidate):
                        days.append(candidate)
        elif self.bydays:
            # Generate all days in month that match bydays
            for d in range(1, last_day + 1):
                candidate = datetime.date(year, month, d)
                if self._day_matches_bydays(candidate):
                    days.append(candidate)

        return days

    def _yearly_occurrences(self, base_date):
        """Get all occurrences in the same year as base_date."""
        year = base_date.year
        days = []

        if not self.bydays and not self.bymonthdays and not self.bymonths:
            # Just this date
            try:
                days.append(datetime.date(year, base_date.month, base_date.day))
            except ValueError:
                pass
            return days

        months_to_check = self.bymonths if self.bymonths else range(1, 13)

        import calendar
        for month in months_to_check:
            last_day = calendar.monthrange(year, month)[1]

            if self.bymonthdays:
                for md in self.bymonthdays:
                    if md > 0:
                        d = md
                    else:
                        d = last_day + md + 1
                    if 1 <= d <= last_day:
                        candidate = datetime.date(year, month, d)
                        if self._day_matches_bydays(candidate):
                            days.append(candidate)
            elif self.bydays:
                for d in range(1, last_day + 1):
                    candidate = datetime.date(year, month, d)
                    if self._day_matches_bydays(candidate):
                        days.append(candidate)
            else:
                try:
                    days.append(datetime.date(year, month, base_date.day))
                except ValueError:
                    pass

        return days

    def _day_matches_bydays(self, day):
        """Check if a day matches the bydays constraints."""
        if not self.bydays:
            return True

        # (day.weekday() + 1) % 7 gives 0=Sun, 1=Mon, ..., 6=Sat
        calc_wd = (day.weekday() + 1) % 7

        simple_days = [d for d in self.bydays if abs(d) < 7]
        positional_days = [d for d in self.bydays if abs(d) >= 7]

        matched = False
        if simple_days:
            if calc_wd in simple_days:
                matched = True
        if positional_days:
            for pd in positional_days:
                if self._matches_positional_byday(day, pd):
                    matched = True
                    break

        return matched


class Appointment:
    """A non-recurring appointment."""
    def __init__(self, start_time, end_time, description, note_hash=None):
        """
        start_time: datetime.datetime (UTC)
        end_time: datetime.datetime (UTC) 
        description: str
        note_hash: str or None
        """
        self.start_time = start_time
        self.end_time = end_time
        self.description = description
        self.note_hash = note_hash

    def start_seconds(self):
        return int(self.start_time.timestamp())

    def end_seconds(self):
        return int(self.end_time.timestamp())

    def duration_seconds(self):
        return int((self.end_time - self.start_time).total_seconds())

    def to_raw(self):
        """Convert to raw file format string."""
        start_str = self.start_time.strftime("%m/%d/%Y") + " @ " + self.start_time.strftime("%H:%M")
        end_str = self.end_time.strftime("%m/%d/%Y") + " @ " + self.end_time.strftime("%H:%M")
        note_part = f">{self.note_hash}" if self.note_hash else ""
        return f"{start_str} -> {end_str}{note_part}|{self.description}"

    def hash(self):
        return sha1_of_string(self.to_raw())

    def occurs_on(self, date):
        """Check if this appointment occurs on the given date."""
        start_date = self.start_time.date()
        end_date = self.end_time.date()
        return start_date <= date <= end_date

    def start_for_display(self, date):
        """Get the display start time for a given date."""
        start_date = self.start_time.date()
        if start_date == date:
            return self.start_time.strftime("%H:%M")
        return "..:..".ljust(5)

    def end_for_display(self, date):
        """Get the display end time for a given date."""
        end_date = self.end_time.date()
        if end_date == date:
            return self.end_time.strftime("%H:%M")
        return "..:..".ljust(5)


class RecurAppointment:
    """A recurring appointment."""
    def __init__(self, start_time, end_time, recur, description, note_hash=None):
        """
        start_time: datetime.datetime
        end_time: datetime.datetime (first occurrence)
        recur: RecurItem
        description: str
        note_hash: str or None
        """
        self.start_time = start_time
        self.end_time = end_time
        self.recur = recur
        self.description = description
        self.note_hash = note_hash

    def duration_seconds(self):
        return int((self.end_time - self.start_time).total_seconds())

    def to_raw(self):
        """Convert to raw file format string."""
        start_str = self.start_time.strftime("%m/%d/%Y") + " @ " + self.start_time.strftime("%H:%M")
        end_str = self.end_time.strftime("%m/%d/%Y") + " @ " + self.end_time.strftime("%H:%M")
        recur_str = self.recur.to_str('%m/%d/%Y')
        note_part = f">{self.note_hash}" if self.note_hash else ""
        return f"{start_str} -> {end_str} {recur_str}{note_part} |{self.description}"

    def hash(self):
        return sha1_of_string(self.to_raw())

    def get_occurrence_dates(self, query_start=None, query_end=None):
        """Get all occurrence dates in the query range."""
        return self.recur.occurrences(self.start_time.date(), query_start, query_end)

    def start_for_display(self, date):
        """Get display start time for a given occurrence date."""
        if date == self.start_time.date():
            return self.start_time.strftime("%H:%M")
        else:
            return "..:..".ljust(5)

    def end_for_display(self, date):
        """Get display end time for a given occurrence date."""
        duration = self.duration_seconds()
        start_of_day = datetime.datetime.combine(date, datetime.time(0, 0, 0))
        occurrence_start = datetime.datetime.combine(date, self.start_time.time())
        occurrence_end = occurrence_start + datetime.timedelta(seconds=duration)

        end_date = occurrence_end.date()
        if end_date == date:
            return occurrence_end.strftime("%H:%M")
        return "..:..".ljust(5)

    def get_occurrence_start(self, occ_date):
        """Get the start datetime for a given occurrence date."""
        return datetime.datetime.combine(occ_date, self.start_time.time())

    def get_occurrence_end(self, occ_date):
        """Get the end datetime for a given occurrence date."""
        return self.get_occurrence_start(occ_date) + datetime.timedelta(seconds=self.duration_seconds())


class Event:
    """A non-recurring all-day event."""
    def __init__(self, date, priority, description, note_hash=None):
