"""
iCalendar import/export for calcurse.
"""
import datetime
import hashlib
import os
import re
import sys
import tempfile

from .data import (
    Appointment, RecurAppointment, Event, RecurEvent, TodoItem, RecurItem,
    sha1_of_string, FREQ_DAILY, FREQ_WEEKLY, FREQ_MONTHLY, FREQ_YEARLY
)


def unescape_ical(s):
    """Unescape iCalendar string."""
    s = s.replace('\\n', '\n')
    s = s.replace('\\N', '\n')
    s = s.replace('\\,', ',')
    s = s.replace('\\;', ';')
    s = s.replace('\\\\', '\\')
    return s


def escape_ical(s):
    """Escape a string for iCalendar."""
    s = s.replace('\\', '\\\\')
    s = s.replace(';', '\\;')
    s = s.replace(',', '\\,')
    s = s.replace('\n', '\\n')
    return s


def parse_ical_datetime(s, is_date_only=False):
    """Parse an iCalendar date/datetime string."""
    s = s.strip()
    if is_date_only or (len(s) == 8 and not 'T' in s):
        # DATE format: YYYYMMDD
        try:
            return datetime.datetime.strptime(s, '%Y%m%d')
        except ValueError:
            return None
    elif s.endswith('Z'):
        # UTC datetime
        try:
            return datetime.datetime.strptime(s, '%Y%m%dT%H%M%SZ')
        except ValueError:
            return None
    elif 'T' in s:
        # Local datetime
        try:
            return datetime.datetime.strptime(s, '%Y%m%dT%H%M%S')
        except ValueError:
            return None
    return None


def parse_ical_duration(s):
    """Parse an iCalendar DURATION value.
    Returns total seconds as integer, or None on failure."""
    s = s.strip()
    # Format: P[nW][nD][T[nH][nM][nS]]
    # or P[nDT][nH][nM][nS] etc.

    match = re.match(
        r'^P(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$',
        s
    )
    if not match:
        return None

    weeks = int(match.group(1) or 0)
    days = int(match.group(2) or 0)
    hours = int(match.group(3) or 0)
    minutes = int(match.group(4) or 0)
    seconds = int(match.group(5) or 0)

    total = (weeks * 7 + days) * 86400 + hours * 3600 + minutes * 60 + seconds
    return total


def duration_to_ical(seconds):
    """Convert seconds to iCalendar DURATION string."""
    if seconds == 0:
        return "P0D"

    days = seconds // 86400
    remaining = seconds % 86400
    hours = remaining // 3600
    remaining = remaining % 3600
    minutes = remaining // 60
    secs = remaining % 60

    s = 'P'
    if days:
        s += f"{days}D"
    if hours or minutes or secs:
        s += 'T'
        if hours:
            s += f"{hours}H"
        if minutes:
            s += f"{minutes}M"
        if secs == 0 and (days == 0 or hours or minutes):
            pass  # Don't add 0S unless needed
        # Actually we need to match the exact format calcurse outputs

    return s


def _duration_to_ical_exact(seconds):
    """Convert seconds to iCalendar DURATION in calcurse's exact format."""
    days = seconds // 86400
    remaining = seconds % 86400
    hours = remaining // 3600
    remaining = remaining % 3600
    minutes = remaining // 60
    # Note: calcurse drops seconds from output

    if days > 0:
        return f"P{days}DT{hours}H{minutes}M0S"
    else:
        return f"P0DT{hours}H{minutes}M0S"


def parse_ical_rrule(rrule_str):
    """Parse an RRULE string into a RecurItem-compatible structure.
    Returns dict with keys: freq, interval, until, count, bydays, bymonthdays, bymonths, wkst
    """
    parts = {}
    for part in rrule_str.split(';'):
        if '=' in part:
            k, _, v = part.partition('=')
            parts[k.strip()] = v.strip()

    freq = parts.get('FREQ', '')
    if freq not in ('DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY'):
        return None  # Unsupported frequency

    interval = int(parts.get('INTERVAL', '1'))
    count = int(parts['COUNT']) if 'COUNT' in parts else None
    wkst = parts.get('WKST', 'MO')

    until = None
    if 'UNTIL' in parts:
        u = parts['UNTIL']
        until_dt = parse_ical_datetime(u)
        if until_dt:
            until = until_dt.date()

    # Parse BYDAY
    bydays_raw = parts.get('BYDAY', '')
    bydays = []
    if bydays_raw:
        day_map = {'SU': 0, 'MO': 1, 'TU': 2, 'WE': 3, 'TH': 4, 'FR': 5, 'SA': 6}
        for byday in bydays_raw.split(','):
            byday = byday.strip()
            m = re.match(r'^(-?\d+)?([A-Z]{2})$', byday)
            if m:
                pos = m.group(1)
                day_abbr = m.group(2)
                if day_abbr in day_map:
                    wd = day_map[day_abbr]
                    if pos:
                        n = int(pos)
                        # Encode as sign(n) * (abs(n)*7 + wd)
                        if n >= 0:
                            encoded = n * 7 + wd
                        else:
                            encoded = -((-n) * 7 + wd)
                        bydays.append(encoded)
                    else:
                        bydays.append(wd)

    # Parse BYMONTHDAY
    bymonthdays = []
    if 'BYMONTHDAY' in parts:
        for md in parts['BYMONTHDAY'].split(','):
            try:
                bymonthdays.append(int(md.strip()))
            except ValueError:
                pass

    # Parse BYMONTH
    bymonths = []
    if 'BYMONTH' in parts:
        for m in parts['BYMONTH'].split(','):
            try:
                bymonths.append(int(m.strip()))
            except ValueError:
                pass

    # Parse BYWEEKNO
    byweekno = []
    if 'BYWEEKNO' in parts:
        for wn in parts['BYWEEKNO'].split(','):
            try:
                byweekno.append(int(wn.strip()))
            except ValueError:
                pass

    freq_map = {
        'DAILY': FREQ_DAILY,
        'WEEKLY': FREQ_WEEKLY,
        'MONTHLY': FREQ_MONTHLY,
        'YEARLY': FREQ_YEARLY,
    }

    return {
        'freq': freq_map[freq],
        'interval': interval,
        'until': until,
        'count': count,
        'bydays': bydays,
        'bymonthdays': bymonthdays,
        'bymonths': bymonths,
        'byweekno': byweekno,
        'wkst': wkst,
        'original_freq': freq,
    }


def compute_until_from_count(start_dt, freq, interval, count, bydays, bymonthdays, bymonths, wkst):
    """Compute the UNTIL date from a COUNT value."""
    if count is None or count <= 0:
        return None

    # Create a RecurItem and generate occurrences
    recur = RecurItem(freq, interval, None, [], bydays, bymonthdays, bymonths)

    # Generate up to 'count' occurrences
    end_limit = datetime.date(2038, 1, 1)
    occurrences = recur.occurrences(start_dt.date(), start_dt.date(), end_limit)

    if len(occurrences) >= count:
        return occurrences[count - 1]
    elif occurrences:
        return occurrences[-1]
    return None


def parse_ical_property(line):
    """Parse a single iCal property line.
    Returns (name, params, value) or None.
    The params dict contains parameter name -> value mappings.
    Handles parameter values that may contain quoted strings with special chars.
    """
    # Split property name from params/value
    # But we need to handle quoted strings in parameters

    # Find the first ':' that's not in a quoted string
    params_dict = {}

    # Find semicolons and colons, respecting quoted strings
    i = 0
    name_end = -1
    in_quote = False
    param_start = -1
    colon_pos = -1

    while i < len(line):
        c = line[i]
        if c == '"':
            in_quote = not in_quote
        elif not in_quote:
            if c == ';' and name_end == -1 and colon_pos == -1:
                name_end = i
                param_start = i + 1
            elif c == ':' and colon_pos == -1:
                if name_end == -1:
                    name_end = i
                colon_pos = i
                break
        i += 1

    if colon_pos == -1:
        return None

    name = line[:name_end].strip().upper()
    value = line[colon_pos + 1:]

    # Parse parameters
    if param_start > 0:
        params_str = line[param_start:colon_pos]
        # Split by semicolons, respecting quotes
        params_parts = []
        current = []
        in_q = False
        for c in params_str:
            if c == '"':
                in_q = not in_q
                current.append(c)
            elif c == ';' and not in_q:
                params_parts.append(''.join(current))
                current = []
            else:
                current.append(c)
        if current:
            params_parts.append(''.join(current))

        for param in params_parts:
            if '=' in param:
                pk, _, pv = param.partition('=')
                params_dict[pk.strip().upper()] = pv.strip().strip('"')

    return name, params_dict, value


def build_note_content(description, location, comment, note_type=None):
    """Build the content of a note file from components."""
    parts = []

    if description is not None:
        parts.append(description)

    # Add separator and metadata if needed
    meta = []
    if location:
        meta.append(f"Location: {location}")
    if comment:
        comment_lines = comment.split('\n')
        first = comment_lines[0]
        rest = comment_lines[1:]
        meta.append(f"Comment: {first}")
        for line in rest:
            meta.append(f"    {line}")
    if note_type:
        meta.append(f"Import: {note_type}")

    if meta:
        parts.append("-- ")
        parts.extend(meta)

    if parts:
        content = '\n'.join(parts) + '\n'
    else:
        content = '\n'

    return content


def import_ical(ical_path, data_dir, quiet=False, dump_imported=False, 
                format_apt=None, format_recur_apt=None, 
                format_event=None, format_recur_event=None,
                format_todo=None):
    """Import iCalendar data from a file.
    Returns (apps, events, todos, skipped, error_file) counts.
    """

    try:
        with open(ical_path, 'r', encoding='utf-8', errors='replace') as f:
            content = f.read()
    except Exception as e:
        sys.stderr.write(f"Cannot open {ical_path}: {e}\n")
        sys.exit(1)

    # Unfold lines (lines starting with space or tab are continuations)
    lines = content.split('\n')
    unfolded = []
    for line in lines:
        line = line.rstrip('\r')
        if line and line[0] in (' ', '\t') and unfolded:
            unfolded[-1] += line[1:]  # Remove the leading whitespace
        else:
            unfolded.append(line)

    total_lines = len(lines)

    apts = []
    recur_apts = []
    evts = []
    recur_evts = []
    todos = []
    skipped = 0
    errors = []

    notes_dir = os.path.join(data_dir, 'notes')
    os.makedirs(notes_dir, exist_ok=True)

    # Parse VCALENDAR
    i = 0
    in_vcal = False
    in_vevent = False
    in_vtodo = False
    current_item = {}

    while i < len(unfolded):
        line = unfolded[i]
        i += 1

        stripped = line.strip()
        if not stripped:
            continue

        parsed = parse_ical_property(stripped)
        if parsed is None:
            continue

        name, params, value = parsed

        if name == 'BEGIN':
            if value.strip() == 'VCALENDAR':
                in_vcal = True
            elif value.strip() == 'VEVENT' and in_vcal:
                in_vevent = True
                current_item = {}
            elif value.strip() == 'VTODO' and in_vcal:
                in_vtodo = True
                current_item = {}
        elif name == 'END':
            if value.strip() == 'VEVENT' and in_vevent:
                in_vevent = False
                result = _process_vevent(current_item, data_dir, errors)
                if result:
                    if isinstance(result, Appointment):
                        apts.append(result)
                    elif isinstance(result, RecurAppointment):
                        recur_apts.append(result)
                    elif isinstance(result, Event):
                        evts.append(result)
                    elif isinstance(result, RecurEvent):
                        recur_evts.append(result)
                else:
                    skipped += 1
            elif value.strip() == 'VTODO' and in_vtodo:
                in_vtodo = False
                result = _process_vtodo(current_item, data_dir, errors)
                if result:
                    todos.append(result)
                else:
                    skipped += 1
            elif value.strip() == 'VCALENDAR':
                in_vcal = False
        elif in_vevent or in_vtodo:
            if name == 'DTSTART':
                current_item['DTSTART'] = (params, value.strip())
            elif name == 'DTEND':
                current_item['DTEND'] = (params, value.strip())
            elif name == 'DURATION':
                current_item['DURATION'] = value.strip()
            elif name == 'SUMMARY':
                if 'SUMMARY' not in current_item:
                    # Handle multi-line summaries
                    current_item['SUMMARY'] = unescape_ical(value)
                    # Check if the value contains a newline
                    if '\n' in current_item['SUMMARY']:
                        current_item['SUMMARY'] = current_item['SUMMARY'].replace('\n', ' ').strip()
            elif name == 'DESCRIPTION':
                current_item['DESCRIPTION'] = unescape_ical(value)
            elif name == 'COMMENT':
                if 'COMMENT' not in current_item:
                    current_item['COMMENT'] = unescape_ical(value)
                else:
                    current_item['COMMENT'] += '\n' + unescape_ical(value)
            elif name == 'LOCATION':
                if 'LOCATION' not in current_item:
                    current_item['LOCATION'] = value  # Don't unescape, preserve as-is
            elif name == 'RRULE':
                current_item['RRULE'] = value.strip()
            elif name == 'EXDATE':
                if 'EXDATE' not in current_item:
                    current_item['EXDATE'] = []
                current_item['EXDATE_PARAMS'] = params
                current_item['EXDATE'].append((params, value.strip()))
            elif name == 'PRIORITY':
                current_item['PRIORITY'] = value.strip()
            elif name == 'STATUS':
                current_item['STATUS'] = value.strip()

    # Load existing data
    from .fileio import parse_apts_file, parse_todo_file, save_apts_file, save_todo_file
    apts_path = os.path.join(data_dir, 'apts')
    todo_path = os.path.join(data_dir, 'todo')

    existing_apts, existing_recur_apts, existing_events, existing_recur_events = \
        parse_apts_file(apts_path)
    existing_todos = parse_todo_file(todo_path)

    # Add new items
    all_apts = existing_apts + apts
    all_recur_apts = existing_recur_apts + recur_apts
    all_events = existing_events + evts
    all_recur_events = existing_recur_events + recur_evts
    all_todos = existing_todos + todos

    # Save
    save_apts_file(apts_path, all_apts, all_recur_apts, all_events, all_recur_events)
    save_todo_file(todo_path, all_todos)

    # Count output items
    n_apps = len(apts) + len(recur_apts)
    n_events = len(evts) + len(recur_evts)
    n_todos = len(todos)

    has_errors = len(errors) > 0
    error_file = None

    if has_errors:
        # Write errors to temp file
        tf = tempfile.NamedTemporaryFile(mode='w', prefix='calcurse_log.', 
                                          delete=False, suffix='')
        error_file = tf.name
        for err in errors:
            tf.write(err + '\n')
        tf.close()

    if dump_imported:
        # Print imported items using format strings
        all_new_items = []
        for item in recur_evts:
            all_new_items.append(('recur-event', item))
        for item in evts:
            all_new_items.append(('event', item))
        for item in recur_apts:
            all_new_items.append(('recur-apt', item))
        for item in apts:
            all_new_items.append(('apt', item))
        for item in todos:
            all_new_items.append(('todo', item))

        from .format import format_item
        for item_type, item in all_new_items:
            fmt = None
            if item_type == 'apt':
                fmt = format_apt or '%(raw)'
            elif item_type == 'recur-apt':
                fmt = format_recur_apt or '%(raw)'
            elif item_type == 'event':
                fmt = format_event or '%(raw)'
            elif item_type == 'recur-event':
                fmt = format_recur_event or '%(raw)'
            elif item_type == 'todo':
                fmt = format_todo or '%(raw)'

            if fmt:
                output = format_item(item, fmt, None)
                print(output, end='')

    return n_apps, n_events, n_todos, skipped, error_file, total_lines


def _get_dtstart_info(item):
    """Get start datetime and whether it's date-only."""
    if 'DTSTART' not in item:
        return None, False, None

    params, value = item['DTSTART']
    value_type = params.get('VALUE', '')
    tzid = params.get('TZID', '')

    is_date = value_type == 'DATE' or (len(value) == 8 and 'T' not in value)

    if not value:
        return None, is_date, tzid

    dt = parse_ical_datetime(value, is_date)
    return dt, is_date, tzid


def _get_dtend_info(item):
    """Get end datetime and whether it's date-only."""
    if 'DTEND' not in item:
        return None, False, None

    params, value = item['DTEND']
    value_type = params.get('VALUE', '')
    tzid = params.get('TZID', '')

    is_date = value_type == 'DATE' or (len(value) == 8 and 'T' not in value)

    if not value:
        return None, is_date, tzid

    dt = parse_ical_datetime(value, is_date)
    return dt, is_date, tzid


def _make_note(description, location, comment, note_type=None):
    """Create a Note from the given parts. Returns (note_hash, content) or (None, None)."""
    from .data import Note

    # Build note content
    needs_note = (description is not None) or location or comment or note_type

    if not needs_note:
        return None, None

    content = build_note_content(description, location, comment, note_type)

    note = Note(content)
    return note.filename, content


def _save_note(notes_dir, note_hash, content):
    """Save a note file."""
    path = os.path.join(notes_dir, note_hash)
    with open(path, 'w') as f:
        f.write(content)


def _process_vevent(item, data_dir, errors):
    """Process a VEVENT and return an appointment or event, or None on failure."""
    notes_dir = os.path.join(data_dir, 'notes')

    start_dt, is_date, tzid = _get_dtstart_info(item)

    if start_dt is None:
        errors.append("Missing or invalid DTSTART")
        return None

    # Get summary/description
    summary = item.get('SUMMARY', '')
    # Handle multi-line summaries from ical (split at first newline)
    if '\n' in summary:
        summary = summary.split('\n')[0].strip()

    description_text = item.get('DESCRIPTION', None)
    location = item.get('LOCATION', None)
    comment = item.get('COMMENT', None)

    # Determine note type for TZID
    note_type = None
    if tzid:
        note_type = f"TZID={tzid}"

    # Build note
    # Notes are created from DESCRIPTION + LOCATION + COMMENT
    note_hash = None
    note_content = None

    if description_text is not None or location or comment or note_type:
        # Need a note
        note_hash, note_content = _make_note(description_text, location, comment, note_type)
        if note_hash:
            _save_note(notes_dir, note_hash, note_content)

    # Check for RRULE
    rrule_str = item.get('RRULE', None)

    # Get EXDATE
    exdates = []
    if 'EXDATE' in item:
        for params, value in item['EXDATE']:
            value_type = params.get('VALUE', '')
            is_date_exdate = value_type == 'DATE'
            for exc_str in value.split(','):
                exc_str = exc_str.strip()
                exc_dt = parse_ical_datetime(exc_str, is_date_exdate)
                if exc_dt:
                    exdates.append(exc_dt.date())

    if is_date:
        # All-day event
        start_date = start_dt.date()

        # Check for DTEND or DURATION
        end_dt, end_is_date, _ = _get_dtend_info(item)
        duration_str = item.get('DURATION', None)

        if duration_str and end_dt:
            errors.append(f"Both DTEND and DURATION specified for '{summary}', skipping")
            return None

        if end_dt:
            if not end_is_date:
                errors.append(f"Invalid DTEND value type for '{summary}', skipping")
                return None
            # Check for DTEND value type mismatch

        if duration_str:
            duration = parse_ical_duration(duration_str)
            if duration is None:
                errors.append(f"Invalid DURATION for '{summary}', skipping")
                return None
            # For DATE events, duration should be in days or weeks
            if duration % 86400 != 0:
                errors.append(f"Invalid duration for all-day event '{summary}', skipping")
                return None
            end_date = start_date + datetime.timedelta(seconds=duration)
        elif end_dt:
            end_date = end_dt.date()
        else:
            end_date = start_date + datetime.timedelta(days=1)

        # Check for multi-day event (end_date - start_date > 1 day)
        days = (end_date - start_date).days

        if rrule_str:
            # Parse RRULE
            rrule = parse_ical_rrule(rrule_str)
            if rrule is None:
                errors.append(f"Unsupported RRULE for '{summary}', skipping")
                return None

            freq = rrule['freq']
            interval = rrule['interval']
            until = rrule['until']
            count = rrule['count']
            bydays = rrule['bydays']
            bymonthdays = rrule['bymonthdays']
            bymonths = rrule['bymonths']

            if count and until is None:
                until = compute_until_from_count(start_dt, freq, interval, count,
                                                  bydays, bymonthdays, bymonths, rrule.get('wkst', 'MO'))

            # Validate EXDATE for DATE type
            if 'EXDATE' in item:
                for params, value in item['EXDATE']:
                    value_type = params.get('VALUE', '')
                    if value_type != 'DATE':
                        errors.append(f"Invalid EXDATE value type for '{summary}', skipping exdates")
                        exdates = []
                        break

            # Check for UNTIL value format (DATE events need DATE UNTIL)
            if rrule.get('original_freq') and 'UNTIL' in rrule_str.upper():
                m = re.search(r'UNTIL=(\d+(?:T\d+Z?)?)', rrule_str, re.I)
                if m:
                    until_val = m.group(1)
                    # For DATE events, UNTIL should be a date
                    if 'T' in until_val and until_val.endswith('Z'):
                        # This is a datetime with Z suffix - allowed for DATE events
                        pass
                    elif 'T' in until_val:
                        errors.append(f"Invalid UNTIL value for '{summary}', skipping")
                        return None

            recur = RecurItem(freq, interval, until, exdates, bydays, bymonthdays, bymonths)

            if days > 1:
                # Multi-day recurring event - needs special handling
                # Convert to recurring appointment spanning multiple days
                # Add note about conversion
                note_import = "multi-day event changed to one-day event"
                if note_hash:
                    # Need to update the note to add the import note
                    note_path = os.path.join(notes_dir, note_hash)
                    with open(note_path, 'r') as f:
                        existing = f.read()

                    if '-- \n' in existing or existing.endswith('-- \n'):
                        updated = existing.rstrip('\n') + f"\nImport: {note_import}\n"
                    else:
                        updated = existing.rstrip('\n') + f"\n-- \nImport: {note_import}\n"

                    new_hash = hashlib.sha1(updated.encode('utf-8', errors='replace')).hexdigest()
                    _save_note(notes_dir, new_hash, updated)
                    note_hash = new_hash
                else:
                    note_hash, note_content = _make_note(None, None, None, note_import)
                    if note_hash:
                        _save_note(notes_dir, note_hash, note_content)

                return RecurEvent(start_date, 1, recur, summary, note_hash)

            return RecurEvent(start_date, 1, recur, summary, note_hash)
        else:
            # Non-recurring event
            if days <= 1:
                return Event(start_date, 1, summary, note_hash)
            else:
                # Multi-day event - convert to recurring
                recur = RecurItem(FREQ_DAILY, 1, 
                                  start_date + datetime.timedelta(days=days-1),
                                  [], [], [], [])

                if note_hash:
                    note_path = os.path.join(notes_dir, note_hash)
                    with open(note_path, 'r') as f:
                        existing = f.read()

                    note_import = "multi-day event changed to one-day event"
                    if '-- \n' in existing:
                        updated = existing.rstrip('\n') + f"\nImport: {note_import}\n"
                    else:
                        updated = existing.rstrip('\n') + f"\n-- \nImport: {note_import}\n"

                    new_hash = hashlib.sha1(updated.encode('utf-8', errors='replace')).hexdigest()
                    _save_note(notes_dir, new_hash, updated)
                    note_hash = new_hash
                else:
                    note_import = "multi-day event changed to one-day event"
                    note_hash, note_content = _make_note(None, None, None, note_import)
                    if note_hash:
                        _save_note(notes_dir, note_hash, note_content)

                return RecurEvent(start_date, 1, recur, summary, note_hash)

    else:
        # Datetime appointment
        # Check for DTEND or DURATION
        end_dt, end_is_date, _ = _get_dtend_info(item)
        duration_str = item.get('DURATION', None)

        if duration_str and end_dt:
            errors.append(f"Both DTEND and DURATION specified for '{summary}', skipping")
            return None

        if end_dt:
            if end_is_date:
                errors.append(f"DTEND value type mismatch for '{summary}', skipping")
                return None
            end_datetime = end_dt
        elif duration_str:
            duration = parse_ical_duration(duration_str)
            if duration is None:
                errors.append(f"Invalid DURATION for '{summary}', skipping")
                return None
            end_datetime = start_dt + datetime.timedelta(seconds=duration)
        else:
            end_datetime = start_dt  # Punctual appointment

        if end_datetime < start_dt:
            errors.append(f"End time before start time for '{summary}', skipping")
            return None

        if rrule_str:
            # Recurring appointment
            rrule = parse_ical_rrule(rrule_str)
            if rrule is None:
                errors.append(f"Unsupported RRULE for '{summary}', skipping")
                return None

            freq = rrule['freq']
            interval = rrule['interval']
            until = rrule['until']
            count = rrule['count']
            bydays = rrule['bydays']
            bymonthdays = rrule['bymonthdays']
            bymonths = rrule['bymonths']

            if count and until is None:
                until = compute_until_from_count(start_dt, freq, interval, count,
                                                  bydays, bymonthdays, bymonths, rrule.get('wkst', 'MO'))

            recur = RecurItem(freq, interval, until, exdates, bydays, bymonthdays, bymonths)
            return RecurAppointment(start_dt, end_datetime, recur, summary, note_hash)
        else:
            return Appointment(start_dt, end_datetime, summary, note_hash)


def _process_vtodo(item, data_dir, errors):
    """Process a VTODO and return a TodoItem, or None on failure."""
    notes_dir = os.path.join(data_dir, 'notes')

    summary = item.get('SUMMARY', None)
    if summary is None:
        # No summary - check if we're at end of file
        errors.append("Missing SUMMARY for todo, skipping")
        return None

    priority_str = item.get('PRIORITY', '9')
    try:
        priority = int(priority_str)
        if priority < 1 or priority > 9:
            errors.append(f"Invalid priority {priority_str}, skipping")
            return None
    except (ValueError, TypeError):
        errors.append(f"Invalid priority {priority_str}, skipping")
        return None

    status = item.get('STATUS', '').upper()
    completed = status == 'COMPLETED'

    description_text = item.get('DESCRIPTION', None)
    location = item.get('LOCATION', None)
    comment = item.get('COMMENT', None)

    note_hash = None
    if description_text is not None or location or comment:
        note_hash, note_content = _make_note(description_text, location, comment)
        if note_hash:
            _save_note(notes_dir, note_hash, note_content)

    return TodoItem(priority, summary, note_hash, completed)


def export_ical(apts_path, todo_path, data_dir, notes_dir, 
                filter_type=None, filter_pattern=None, filter_hash=None,
                filter_hash_invert=False, export_uid=False,
                filter_start_from=None, filter_start_to=None,
                filter_start_after=None, filter_start_before=None,
                filter_end_from=None, filter_end_to=None):
    """Export data in iCalendar format."""
    from .fileio import parse_apts_file, parse_todo_file

    apts, recur_apts, events, recur_events = parse_apts_file(apts_path)
    todos = parse_todo_file(todo_path)

    print("BEGIN:VCALENDAR")
    print("VERSION:2.0")
    print("PRODID:-//calcurse//NONSGML v4.8.2//EN")

    # Export appointments
    def should_include_apt(item):
        if filter_type and not _type_matches(item, filter_type):
            return False
        return True

    for apt in apts:
        if not should_include_apt(apt):
            continue
        _export_apt_ical(apt, export_uid)

    for apt in recur_apts:
        if not should_include_apt(apt):
            continue
        _export_recur_apt_ical(apt, export_uid)

    for evt in events:
        if not should_include_apt(evt):
            continue
        _export_event_ical(evt, export_uid)

    for evt in recur_events:
        if not should_include_apt(evt):
            continue
        _export_recur_event_ical(evt, export_uid)

    for todo in todos:
        if not should_include_apt(todo):
            continue
        _export_todo_ical(todo, export_uid)

    print("END:VCALENDAR")


def _export_apt_ical(apt, export_uid=False):
    """Export an appointment in iCal format."""
    print("BEGIN:VEVENT")
    if export_uid:
        print(f"UID:{apt.hash()}")
    print(f"DTSTART:{apt.start_time.strftime('%Y%m%dT%H%M%S')}")

    duration = apt.duration_seconds()
    if duration > 0:
        print(f"DURATION:{_duration_to_ical_exact(duration)}")

    print(f"SUMMARY:{escape_ical(apt.description)}")
    print("END:VEVENT")


def _export_recur_apt_ical(apt, export_uid=False):
    """Export a recurring appointment in iCal format."""
    print("BEGIN:VEVENT")
    if export_uid:
        print(f"UID:{apt.hash()}")
    print(f"DTSTART:{apt.start_time.strftime('%Y%m%dT%H%M%S')}")

    duration = apt.duration_seconds()
    if duration > 0:
        print(f"DURATION:{_duration_to_ical_exact(duration)}")

    # RRULE
    rrule = _recur_to_rrule(apt.recur)
    if rrule:
        print(f"RRULE:{rrule}")

    # EXDATE
    for exc in apt.recur.exceptions:
        print(f"EXDATE:{exc.strftime('%Y%m%dT') + apt.start_time.strftime('%H%M%S')}")

    print(f"SUMMARY:{escape_ical(apt.description)}")
    print("END:VEVENT")


def _export_event_ical(evt, export_uid=False):
    """Export an event in iCal format."""
    print("BEGIN:VEVENT")
    if export_uid:
        print(f"UID:{evt.hash()}")
    print(f"DTSTART;VALUE=DATE:{evt.date.strftime('%Y%m%d')}")
    print(f"DURATION:P1D")
    print(f"SUMMARY:{escape_ical(evt.description)}")
    print("END:VEVENT")


def _export_recur_event_ical(evt, export_uid=False):
    """Export a recurring event in iCal format."""
    print("BEGIN:VEVENT")
    if export_uid:
        print(f"UID:{evt.hash()}")
    print(f"DTSTART;VALUE=DATE:{evt.date.strftime('%Y%m%d')}")
    print(f"DURATION:P1D")

    rrule = _recur_to_rrule(evt.recur)
    if rrule:
        print(f"RRULE:{rrule}")

    for exc in evt.recur.exceptions:
        print(f"EXDATE;VALUE=DATE:{exc.strftime('%Y%m%d')}")

    print(f"SUMMARY:{escape_ical(evt.description)}")
    print("END:VEVENT")


def _export_todo_ical(todo, export_uid=False):
    """Export a todo in iCal format."""
    print("BEGIN:VTODO")
    if export_uid:
        print(f"UID:{todo.hash()}")
    if not todo.completed:
        print(f"PRIORITY:{todo.priority}")
    print(f"SUMMARY:{escape_ical(todo.description)}")
    print("END:VTODO")


def _recur_to_rrule(recur):
    """Convert a RecurItem to an RRULE string."""
    freq_map = {
        FREQ_DAILY: 'DAILY',
        FREQ_WEEKLY: 'WEEKLY',
        FREQ_MONTHLY: 'MONTHLY',
        FREQ_YEARLY: 'YEARLY',
    }

    freq_str = freq_map.get(recur.freq, '')
    if not freq_str:
        return None

    parts = [f"FREQ={freq_str}"]
    if recur.interval > 1:
        parts.append(f"INTERVAL={recur.interval}")
    if recur.until:
        parts.append(f"UNTIL={recur.until.strftime('%Y%m%dT000000Z')}")

    return ';'.join(parts)


def _type_matches(item, filter_type):
    """Check if an item matches the type filter."""
    item_types = set()
    if isinstance(item, Appointment):
        item_types.add('apt')
    elif isinstance(item, RecurAppointment):
        item_types.add('recur-apt')
    elif isinstance(item, Event):
        item_types.add('event')
    elif isinstance(item, RecurEvent):
        item_types.add('recur-event')
    elif isinstance(item, TodoItem):
        item_types.add('todo')

    # Check if any type in filter_type matches
    filter_types = set()
    for t in filter_type:
        if t == 'cal':
            filter_types.update(['event', 'apt', 'recur-event', 'recur-apt'])
        elif t == 'recur':
            filter_types.update(['recur-event', 'recur-apt'])
        else:
            filter_types.add(t)

    return bool(item_types & filter_types)


def export_pcal(apts_path, todo_path, data_dir):
    """Export data in pcal format."""
    from .fileio import parse_apts_file, parse_todo_file

    apts, recur_apts, events, recur_events = parse_apts_file(apts_path)
    todos = parse_todo_file(todo_path)

