"""
iCalendar import/export for calcurse.
"""
import datetime
import hashlib
import os
import re
import sys
import tempfile

from .data import (
    Appointment, RecurAppointment, Event, RecurEvent, TodoItem, RecurItem,
    sha1_of_string, FREQ_DAILY, FREQ_WEEKLY, FREQ_MONTHLY, FREQ_YEARLY
)


def unescape_ical(s):
    """Unescape iCalendar string."""
    s = s.replace('\\n', '\n')
    s = s.replace('\\N', '\n')
    s = s.replace('\\,', ',')
    s = s.replace('\\;', ';')
    s = s.replace('\\\\', '\\')
    return s


def escape_ical(s):
    """Escape a string for iCalendar."""
    s = s.replace('\\', '\\\\')
    s = s.replace(';', '\\;')
    s = s.replace(',', '\\,')
    s = s.replace('\n', '\\n')
    return s


def parse_ical_datetime(s, is_date_only=False):
    """Parse an iCalendar date/datetime string."""
    s = s.strip()
    if is_date_only or (len(s) == 8 and not 'T' in s):
        # DATE format: YYYYMMDD
        try:
            return datetime.datetime.strptime(s, '%Y%m%d')
        except ValueError:
            return None
    elif s.endswith('Z'):
        # UTC datetime
        try:
            return datetime.datetime.strptime(s, '%Y%m%dT%H%M%SZ')
        except ValueError:
            return None
    elif 'T' in s:
        # Local datetime
        try:
            return datetime.datetime.strptime(s, '%Y%m%dT%H%M%S')
        except ValueError:
            return None
    return None


def parse_ical_duration(s):
    """Parse an iCalendar DURATION value.
    Returns total seconds as integer, or None on failure."""
    s = s.strip()
    # Format: P[nW][nD][T[nH][nM][nS]]
    # or P[nDT][nH][nM][nS] etc.

    match = re.match(
        r'^P(?:(\d+)W)?(?:(\d+)D)?(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$',
        s
    )
    if not match:
        return None

    weeks = int(match.group(1) or 0)
    days = int(match.group(2) or 0)
    hours = int(match.group(3) or 0)
    minutes = int(match.group(4) or 0)
    seconds = int(match.group(5) or 0)

    total = (weeks * 7 + days) * 86400 + hours * 3600 + minutes * 60 + seconds
    return total


def duration_to_ical(seconds):
    """Convert seconds to iCalendar DURATION string."""
    if seconds == 0:
        return "P0D"

    days = seconds // 86400
    remaining = seconds % 86400
    hours = remaining // 3600
    remaining = remaining % 3600
    minutes = remaining // 60
    secs = remaining % 60

    s = 'P'
    if days:
        s += f"{days}D"
    if hours or minutes or secs:
        s += 'T'
        if hours:
            s += f"{hours}H"
        if minutes:
            s += f"{minutes}M"
        if secs == 0 and (days == 0 or hours or minutes):
            pass  # Don't add 0S unless needed
        # Actually we need to match the exact format calcurse outputs

    return s


def _duration_to_ical_exact(seconds):
    """Convert seconds to iCalendar DURATION in calcurse's exact format."""
    days = seconds // 86400
    remaining = seconds % 86400
    hours = remaining // 3600
    remaining = remaining % 3600
    minutes = remaining // 60
    # Note: calcurse drops seconds from output

    if days > 0:
        return f"P{days}DT{hours}H{minutes}M0S"
    else:
        return f"P0DT{hours}H{minutes}M0S"


def parse_ical_rrule(rrule_str):
    """Parse an RRULE string into a RecurItem-compatible structure.
    Returns dict with keys: freq, interval, until, count, bydays, bymonthdays, bymonths, wkst
    """
    parts = {}
    for part in rrule_str.split(';'):
        if '=' in part:
            k, _, v = part.partition('=')
            parts[k.strip()] = v.strip()

    freq = parts.get('FREQ', '')
    if freq not in ('DAILY', 'WEEKLY', 'MONTHLY', 'YEARLY'):
        return None  # Unsupported frequency

    interval = int(parts.get('INTERVAL', '1'))
    count = int(parts['COUNT']) if 'COUNT' in parts else None
    wkst = parts.get('WKST', 'MO')

    until = None
    if 'UNTIL' in parts:
        u = parts['UNTIL']
        until_dt = parse_ical_datetime(u)
        if until_dt:
            until = until_dt.date()

    # Parse BYDAY
    bydays_raw = parts.get('BYDAY', '')
    bydays = []
    if bydays_raw:
        day_map = {'SU': 0, 'MO': 1, 'TU': 2, 'WE': 3, 'TH': 4, 'FR': 5, 'SA': 6}
        for byday in bydays_raw.split(','):
            byday = byday.strip()
            m = re.match(r'^(-?\d+)?([A-Z]{2})$', byday)
            if m:
                pos = m.group(1)
                day_abbr = m.group(2)
                if day_abbr in day_map:
                    wd = day_map[day_abbr]
                    if pos:
                        n = int(pos)
                        # Encode as sign(n) * (abs(n)*7 + wd)
                        if n >= 0:
                            encoded = n * 7 + wd
                        else:
                            encoded = -((-n) * 7 + wd)
                        bydays.append(encoded)
                    else:
                        bydays.append(wd)

    # Parse BYMONTHDAY
    bymonthdays = []
    if 'BYMONTHDAY' in parts:
        for md in parts['BYMONTHDAY'].split(','):
            try:
                bymonthdays.append(int(md.strip()))
            except ValueError:
                pass

    # Parse BYMONTH
    bymonths = []
    if 'BYMONTH' in parts:
        for m in parts['BYMONTH'].split(','):
            try:
                bymonths.append(int(m.strip()))
            except ValueError:
                pass

    # Parse BYWEEKNO
    byweekno = []
    if 'BYWEEKNO' in parts:
        for wn in parts['BYWEEKNO'].split(','):
            try:
                byweekno.append(int(wn.strip()))
            except ValueError:
                pass

    freq_map = {
        'DAILY': FREQ_DAILY,
        'WEEKLY': FREQ_WEEKLY,
        'MONTHLY': FREQ_MONTHLY,
        'YEARLY': FREQ_YEARLY,
    }

    return {
        'freq': freq_map[freq],
        'interval': interval,
        'until': until,
        'count': count,
        'bydays': bydays,
        'bymonthdays': bymonthdays,
        'bymonths': bymonths,
        'byweekno': byweekno,
        'wkst': wkst,
        'original_freq': freq,
    }


def compute_until_from_count(start_dt, freq, interval, count, bydays, bymonthdays, bymonths, wkst):
    """Compute the UNTIL date from a COUNT value."""
    if count is None or count <= 0:
        return None

    # Create a RecurItem and generate occurrences
    recur = RecurItem(freq, interval, None, [], bydays, bymonthdays, bymonths)

    # Generate up to 'count' occurrences
    end_limit = datetime.date(2038, 1, 1)
    occurrences = recur.occurrences(start_dt.date(), start_dt.date(), end_limit)

    if len(occurrences) >= count:
        return occurrences[count - 1]
    elif occurrences:
        return occurrences[-1]
    return None


def parse_ical_property(line):
    """Parse a single iCal property line.
    Returns (name, params, value) or None.
    The params dict contains parameter name -> value mappings.
    Handles parameter values that may contain quoted strings with special chars.
    """
    # Split property name from params/value
    # But we need to handle quoted strings in parameters

    # Find the first ':' that's not in a quoted string
    params_dict = {}

    # Find semicolons and colons, respecting quoted strings
    i = 0
    name_end = -1
    in_quote = False
    param_start = -1
    colon_pos = -1

    while i < len(line):
        c = line[i]
        if c == '"':
            in_quote = not in_quote
        elif not in_quote:
            if c == ';' and name_end == -1 and colon_pos == -1:
                name_end = i
                param_start = i + 1
            elif c == ':' and colon_pos == -1:
                if name_end == -1:
                    name_end = i
                colon_pos = i
                break
        i += 1

    if colon_pos == -1:
        return None

    name = line[:name_end].strip().upper()
    value = line[colon_pos + 1:]

    # Parse parameters
    if param_start > 0:
        params_str = line[param_start:colon_pos]
        # Split by semicolons, respecting quotes
        params_parts = []
        current = []
        in_q = False
        for c in params_str:
            if c == '"':
                in_q = not in_q
                current.append(c)
            elif c == ';' and not in_q:
                params_parts.append(''.join(current))
                current = []
            else:
                current.append(c)
        if current:
            params_parts.append(''.join(current))

        for param in params_parts:
            if '=' in param:
                pk, _, pv = param.partition('=')
                params_dict[pk.strip().upper()] = pv.strip().strip('"')

    return name, params_dict, value


def build_note_content(description, location, comment, note_type=None):
    """Build the content of a note file from components."""
    parts = []

    if description is not None:
        parts.append(description)

    # Add separator and metadata if needed
    meta = []
    if location:
        meta.append(f"Location: {location}")
    if comment:
        comment_lines = comment.split('\n')
        first = comment_lines[0]
        rest = comment_lines[1:]
        meta.append(f"Comment: {first}")
        for line in rest:
            meta.append(f"    {line}")
    if note_type:
        meta.append(f"Import: {note_type}")

    if meta:
        parts.append("-- ")
        parts.extend(meta)

    if parts:
        content = '\n'.join(parts) + '\n'
    else:
        content = '\n'

    return content


def import_ical(ical_path, data_dir, quiet=False, dump_imported=False, 
