"""
Format specifiers for calcurse output.
"""
import datetime
import re
import time

from .data import (
    Appointment, RecurAppointment, Event, RecurEvent, TodoItem
)


def format_duration(seconds, fmt=None):
    """Format a duration in seconds.
    fmt: optional strftime-like format string with %d, %H, %M, %S modifiers.
    Without fmt, returns total seconds as string.
    """
    if fmt is None:
        return str(seconds)

    # Parse the format string for duration specifiers
    result = []
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c == '%' and i + 1 < len(fmt):
            i += 1
            # Check for flags
            flags = ''
            while i < len(fmt) and fmt[i] in ('-', 'E'):
                flags += fmt[i]
                i += 1

            if i >= len(fmt):
                break

            spec = fmt[i]
            suppress_pad = '-' in flags
            extend = 'E' in flags

            if spec == 'd':
                days = seconds // 86400
                val = str(days)
                if not suppress_pad:
                    val = val.zfill(2)
                result.append(val)
            elif spec == 'H':
                if extend:
                    hours = seconds // 3600
                else:
                    hours = (seconds // 3600) % 24
                val = str(hours)
                if not suppress_pad:
                    val = val.zfill(2)
                result.append(val)
            elif spec == 'M':
                if extend:
                    minutes = seconds // 60
                else:
                    minutes = (seconds // 60) % 60
                val = str(minutes)
                if not suppress_pad:
                    val = val.zfill(2)
                result.append(val)
            elif spec == 'S':
                if extend:
                    secs = seconds
                else:
                    secs = seconds % 60
                val = str(secs)
                if not suppress_pad:
                    val = val.zfill(2)
                result.append(val)
            else:
                result.append('%')
                if flags:
                    result.append(flags)
                result.append(spec)
        else:
            result.append(c)
        i += 1

    return ''.join(result)


def format_time_extended(epoch_seconds, fmt=None):
    """Format an epoch time.
    fmt: None or 'epoch' -> return epoch seconds
         'default' -> return HH:MM (with continuation marker logic)
         otherwise -> use as strftime format
    """
    if fmt is None or fmt == 'epoch':
        return str(epoch_seconds)

    if fmt == 'default':
        dt = datetime.datetime.utcfromtimestamp(epoch_seconds)
        return dt.strftime('%H:%M')

    # Use as strftime format
    dt = datetime.datetime.utcfromtimestamp(epoch_seconds)
    return dt.strftime(fmt)


def _format_remaining(seconds_remaining):
    """Format remaining time as ±HH:MM."""
    if seconds_remaining >= 0:
        h = seconds_remaining // 3600
        m = (seconds_remaining % 3600) // 60
        return f"{h}:{m:02d}"
    else:
        # Negative remaining
        total = -seconds_remaining
        h = total // 3600
        m = (total % 3600) // 60
        return f"-{h}:{m:02d}"


def parse_extended_spec(spec_str):
    """Parse an extended format specifier like 'start:fmt' or 'duration:%H:%M'.
    Returns (spec_name, fmt_str).
    """
    if ':' in spec_str:
        name, _, fmt = spec_str.partition(':')
        return name.lower(), fmt
    return spec_str.lower(), None


def format_item(item, fmt, occ_date, notes_dir=None, current_time=None):
    """Format an item using the given format string.
    occ_date: datetime.date for the occurrence date (used for multi-day apts)
    """
    if fmt == '%(raw)':
        from .data import sha1_of_string
        raw = item.to_raw()
        return raw + '\n'

    if fmt == '%(hash)':
        return item.hash() + '\n'

    result = []
    i = 0
    while i < len(fmt):
        c = fmt[i]
        if c == '%' and i + 1 < len(fmt):
            i += 1
            nc = fmt[i]

            if nc == '(':
                # Extended specifier %(name[:fmt])
                end = fmt.index(')', i) if ')' in fmt[i:] else len(fmt)
                spec_content = fmt[i+1:end]
                i = end

                spec_name, spec_fmt = parse_extended_spec(spec_content)

                if spec_name == 'raw':
                    result.append(item.to_raw())
                    result.append('\n')
                elif spec_name == 'hash':
                    result.append(item.hash())
                elif spec_name == 'start':
                    # For appointments
                    if isinstance(item, (Appointment, RecurAppointment)):
                        if isinstance(item, Appointment):
                            start_epoch = int(item.start_time.timestamp())
                        else:
                            start_dt = item.get_occurrence_start(occ_date) if occ_date else item.start_time
                            start_epoch = int(start_dt.timestamp())
                        result.append(format_time_extended(start_epoch, spec_fmt))
                elif spec_name == 'end':
                    if isinstance(item, (Appointment, RecurAppointment)):
                        if isinstance(item, Appointment):
                            end_epoch = int(item.end_time.timestamp())
                        else:
                            end_dt = item.get_occurrence_end(occ_date) if occ_date else item.end_time
                            end_epoch = int(end_dt.timestamp())
                        result.append(format_time_extended(end_epoch, spec_fmt))
                elif spec_name == 'duration':
                    if isinstance(item, (Appointment, RecurAppointment)):
                        dur = item.duration_seconds()
                        result.append(format_duration(dur, spec_fmt))
                elif spec_name == 'remaining':
                    if isinstance(item, (Appointment, RecurAppointment)):
                        if isinstance(item, Appointment):
                            start_epoch = int(item.start_time.timestamp())
                        else:
                            start_dt = item.get_occurrence_start(occ_date) if occ_date else item.start_time
                            start_epoch = int(start_dt.timestamp())
                        if current_time is None:
                            current_time = int(time.time())
                        remaining = start_epoch - current_time
                        result.append(format_duration(remaining, spec_fmt))
            elif nc == 'm':
                # Description
                result.append(item.description)
            elif nc == 'n':
                # Note filename
                if hasattr(item, 'note_hash') and item.note_hash:
                    result.append(item.note_hash)
                else:
                    result.append('(null)')
            elif nc == 'N':
                # Note content
                if notes_dir and hasattr(item, 'note_hash') and item.note_hash:
                    note_path = f"{notes_dir}/{item.note_hash}"
                    try:
                        with open(note_path, 'r') as f:
                            result.append(f.read())
                    except Exception:
                        result.append('')
                else:
                    result.append('')
            elif nc == 'p':
                # Priority (for todos)
                if isinstance(item, TodoItem):
                    if item.completed:
                        result.append('0')
                    else:
                        result.append(str(item.priority))
            elif nc == 's':
                # Start time as epoch seconds
                if isinstance(item, Appointment):
                    result.append(str(int(item.start_time.timestamp())))
                elif isinstance(item, RecurAppointment):
                    if occ_date:
                        start_dt = item.get_occurrence_start(occ_date)
                        result.append(str(int(start_dt.timestamp())))
                    else:
                        result.append(str(int(item.start_time.timestamp())))
                elif isinstance(item, Event):
                    result.append(str(item.start_seconds()))
            elif nc == 'e':
                # End time as epoch seconds
                if isinstance(item, Appointment):
                    result.append(str(int(item.end_time.timestamp())))
                elif isinstance(item, RecurAppointment):
                    if occ_date:
                        end_dt = item.get_occurrence_end(occ_date)
                        result.append(str(int(end_dt.timestamp())))
                    else:
                        result.append(str(int(item.end_time.timestamp())))
                elif isinstance(item, Event):
                    result.append(str(item.end_seconds()))
            elif nc == 'S':
                # Start time HH:MM with continuation marker
                if isinstance(item, Appointment) and occ_date:
                    result.append(item.start_for_display(occ_date))
                elif isinstance(item, RecurAppointment) and occ_date:
                    result.append(item.start_for_display(occ_date))
                elif isinstance(item, Appointment):
                    result.append(item.start_time.strftime('%H:%M'))
                elif isinstance(item, RecurAppointment):
                    result.append(item.start_time.strftime('%H:%M'))
            elif nc == 'E':
                # End time HH:MM with continuation marker
                if isinstance(item, Appointment) and occ_date:
                    result.append(item.end_for_display(occ_date))
                elif isinstance(item, RecurAppointment) and occ_date:
                    result.append(item.end_for_display(occ_date))
                elif isinstance(item, Appointment):
                    result.append(item.end_time.strftime('%H:%M'))
                elif isinstance(item, RecurAppointment):
                    result.append(item.end_time.strftime('%H:%M'))
            elif nc == 'd':
                # Duration in seconds
                if isinstance(item, (Appointment, RecurAppointment)):
                    result.append(str(item.duration_seconds()))
            elif nc == 'r':
                # Remaining time
                if isinstance(item, (Appointment, RecurAppointment)):
                    if isinstance(item, Appointment):
                        start_epoch = int(item.start_time.timestamp())
                    else:
                        if occ_date:
                            start_dt = item.get_occurrence_start(occ_date)
                            start_epoch = int(start_dt.timestamp())
                        else:
                            start_epoch = int(item.start_time.timestamp())
                    if current_time is None:
                        current_time = int(time.time())
                    remaining = start_epoch - current_time
                    result.append(_format_remaining(remaining))
            elif nc == '\n':
                result.append('\n')
            elif nc == 't':
                result.append('\t')
            elif nc == '%':
                result.append('%')
            else:
                result.append('%')
                result.append(nc)
        elif c == '\\':
            if i + 1 < len(fmt):
                i += 1
                nc = fmt[i]
                if nc == 'n':
                    result.append('\n')
                elif nc == 't':
                    result.append('\t')
                else:
                    result.append('\\')
                    result.append(nc)
            else:
                result.append('\\')
        else:
            result.append(c)
        i += 1

    return ''.join(result)

