                     config['todo'] is not None)

    is_grep_mode = config['grep']
    is_purge_mode = config['purge']

    if is_grep_mode or is_purge_mode:
        # Load data
        apts, recur_apts, events, recur_events = parse_apts_file(apts_path)
        todos = parse_todo_file(todo_path)

        if is_grep_mode:
            grep_items(apts, recur_apts, events, recur_events, todos,
                       notes_dir=notes_dir,
                       **filter_kwargs, **format_kwargs)
        else:  # purge
            # In purge mode, items that MATCH the filter are REMOVED
            # (invert filter internally)
            new_apts = []
            new_recur_apts = []
            new_events = []
            new_recur_events = []
            new_todos = []

            for item in apts:
                if not matches_filter(item, **filter_kwargs):
                    new_apts.append(item)
            for item in recur_apts:
                if not matches_filter(item, **filter_kwargs):
                    new_recur_apts.append(item)
            for item in events:
                if not matches_filter(item, **filter_kwargs):
                    new_events.append(item)
            for item in recur_events:
                if not matches_filter(item, **filter_kwargs):
                    new_recur_events.append(item)
            for item in todos:
                if not matches_filter(item, **filter_kwargs):
                    new_todos.append(item)

            if not config['read_only']:
                save_apts_file(apts_path, new_apts, new_recur_apts, new_events, new_recur_events)
                save_todo_file(todo_path, new_todos)

        return 0

    if is_query_mode:
        # Handle query mode
        from_date = None
        to_date = None

        if config['appointment']:
            # -a: current day, filter type = cal
            from_date = today
            to_date = today
            if not config['filter_type']:
                config['filter_type'] = parse_filter_type('cal')
                filter_kwargs['filter_type'] = config['filter_type']

        elif config['day'] is not None:
            # -d DATE or -d NUM
            day_arg = config['day']
            try:
                num = int(day_arg)
                # It's a number
                if num >= 0:
                    from_date = today
                    to_date = today + datetime.timedelta(days=num - 1)
                else:
                    from_date = today + datetime.timedelta(days=num + 1)
                    to_date = today
            except ValueError:
                # It's a date
                try:
                    d, _ = parse_date_arg(day_arg, cfg.input_datefmt)
                    from_date = d
                    to_date = d
                except ValueError:
                    sys.stderr.write(f"Invalid date: {day_arg}\n")
                    return 1

            if not config['filter_type']:
                config['filter_type'] = parse_filter_type('cal')
                filter_kwargs['filter_type'] = config['filter_type']

        elif config['next']:
            # -n: next appointment within 24 hours
            apts, recur_apts, events, recur_events = parse_apts_file(apts_path)
            todos = parse_todo_file(todo_path)
            print_next_appointment(apts, recur_apts)
            return 0

        elif config['range'] is not None:
            # -r[NUM]: from today, range of NUM days
            try:
                num = int(config['range'])
            except ValueError:
                num = 1

            if num >= 0:
                from_date = today
                to_date = today + datetime.timedelta(days=num - 1)
            else:
                from_date = today + datetime.timedelta(days=num + 1)
                to_date = today

            if not config['filter_type']:
                config['filter_type'] = parse_filter_type('cal')
                filter_kwargs['filter_type'] = config['filter_type']

        elif config['startday'] is not None:
            # -s[DATE]: from DATE
            if config['startday']:
                try:
                    d, _ = parse_date_arg(config['startday'], cfg.input_datefmt)
                    from_date = d
                except ValueError:
                    from_date = today
            else:
                from_date = today
            to_date = from_date

            if not config['filter_type']:
                config['filter_type'] = parse_filter_type('cal')
                filter_kwargs['filter_type'] = config['filter_type']

        elif config['todo'] is not None:
            # -t[NUM]: todo list
            if config['todo'] == '':
                # All todos
                pass
            else:
                try:
                    n = int(config['todo'])
                    if n == 0:
                        # Completed todos
                        config['filter_completed'] = True
                        filter_kwargs['filter_completed'] = True
                    else:
                        # Uncompleted todos with specific priority
                        config['filter_priority'] = n
                        filter_kwargs['filter_priority'] = n
                        config['filter_uncompleted'] = True
                        filter_kwargs['filter_uncompleted'] = True
                except ValueError:
                    pass

            if not config['filter_type']:
                config['filter_type'] = parse_filter_type('todo')
                filter_kwargs['filter_type'] = config['filter_type']

        elif config['query']:
            # -Q: full query with date range
            pass

        # Handle --from, --to, --days for -Q mode
        if config['query']:
            if config['from_date']:
                try:
                    from_date, _ = parse_date_arg(config['from_date'], cfg.input_datefmt)
                except ValueError:
                    sys.stderr.write(f"Invalid date: {config['from_date']}\n")
                    return 1
            else:
                from_date = today

            if config['to_date']:
                try:
                    to_date, _ = parse_date_arg(config['to_date'], cfg.input_datefmt)
                except ValueError:
                    sys.stderr.write(f"Invalid date: {config['to_date']}\n")
                    return 1
            elif config['days']:
                try:
                    num = int(config['days'])
                    if num > 0:
                        to_date = from_date + datetime.timedelta(days=num - 1)
                    elif num < 0:
                        to_date = from_date
                        from_date = from_date + datetime.timedelta(days=num + 1)
                    else:
                        to_date = from_date
                except ValueError:
                    to_date = from_date
            else:
                to_date = from_date

        # Load data and query
        apts, recur_apts, events, recur_events = parse_apts_file(apts_path)
        todos = parse_todo_file(todo_path)

        # Determine output date format
        output_fmt = cfg.output_datefmt

        query_items(apts, recur_apts, events, recur_events, todos,
                    from_date, to_date if to_date else today,
                    output_datefmt=output_fmt,
                    notes_dir=notes_dir,
                    limit=config.get('limit'),
                    **filter_kwargs, **format_kwargs)

        return 0

    # If no operation specified, enter interactive mode
    from .tui import run_interactive
    return run_interactive(apts_path, todo_path, data_dir, conf_dir, notes_dir, cfg, config)


def do_import(config, apts_path, todo_path, data_dir, notes_dir, cfg):
    """Handle import operation."""
    ical_file = config['import']
    quiet = config['quiet']
    dump_imported = config['dump_imported']

    n_apps, n_events, n_todos, skipped, error_file, total_lines = import_ical(
        ical_file, data_dir, quiet=quiet, dump_imported=dump_imported,
        format_apt=config['format_apt'],
        format_recur_apt=config['format_recur_apt'],
        format_event=config['format_event'],
        format_recur_event=config['format_recur_event'],
        format_todo=config['format_todo'],
    )

    if not quiet:
        app_word = "app" if n_apps == 1 else "apps"
        event_word = "event" if n_events == 1 else "events"
        todo_word = "todo" if n_todos == 1 else "todos"

        print(f"Import process report: {total_lines:04d} lines read")
        print(f"{n_apps} {app_word} / {n_events} {event_word} / {n_todos} {todo_word} / {skipped} skipped")

    if error_file:
        sys.stderr.write(f"\nSome items could not be imported.\n")
        sys.stderr.write(f"See {error_file} for details.\n")
        return 1

    return 0


def do_export(config, apts_path, todo_path, data_dir, notes_dir, cfg):
    """Handle export operation."""
    fmt = config['export']
    if fmt is None or fmt == '' or fmt == 'ical':
        fmt = 'ical'
    elif fmt == 'pcal':
        pass
    else:
        sys.stderr.write(f"args.c: 880: invalid argument combination\n")
        return 1

    if fmt == 'ical':
        export_ical(apts_path, todo_path, data_dir, notes_dir,
                    export_uid=config['export_uid'])
    elif fmt == 'pcal':
        export_pcal(apts_path, todo_path, data_dir)

    return 0


def do_gc(apts_path, todo_path, notes_dir):
    """Run garbage collector to remove orphaned note files."""
    # Load all items and collect referenced note hashes
    from .fileio import parse_apts_file, parse_todo_file

    apts, recur_apts, events, recur_events = parse_apts_file(apts_path)
    todos = parse_todo_file(todo_path)

    referenced = set()
    for item in apts + recur_apts + events + recur_events + todos:
        if hasattr(item, 'note_hash') and item.note_hash:
            referenced.add(item.note_hash)

    # Remove unreferenced note files
    if os.path.exists(notes_dir):
        for fname in os.listdir(notes_dir):
            if fname not in referenced:
                os.remove(os.path.join(notes_dir, fname))

    return 0


