def print_status(data_dir):
    """Print status of running calcurse instances."""
    import glob

    pid_file = os.path.join(data_dir, '.calcurse.pid')
    daemon_log = os.path.join(data_dir, '.daemon.log')

    found_any = False

    if os.path.exists(pid_file):
        try:
            with open(pid_file, 'r') as f:
                pid = int(f.read().strip())
            # Check if process is running
            try:
                os.kill(pid, 0)
                print(f"calcurse is running (pid {pid})")
                found_any = True
            except (ProcessLookupError, PermissionError):
                pass
        except Exception:
            pass

    if os.path.exists(daemon_log):
        try:
            with open(daemon_log, 'r') as f:
                pid_str = f.read().strip()
            if pid_str:
                pid = int(pid_str)
                try:
                    os.kill(pid, 0)
                    print(f"calcurse daemon is running (pid {pid})")
                    found_any = True
                except (ProcessLookupError, PermissionError):
                    pass
        except Exception:
            pass

    if not found_any:
        print("calcurse is not running")


