def parse_filter_type(s):
    """Parse a filter type string into a list of type strings."""
    types = []
    for t in s.split(','):
        t = t.strip().lower()
        if t in ('event', 'apt', 'recur-event', 'recur-apt', 'todo', 'cal', 'recur'):
            types.append(t)
    return types if types else None


def parse_date_arg(s, input_fmt_num):
    """Parse a date argument, return (date, time_minutes_or_None)."""
    return parse_date_with_time(s, input_fmt_num)


